"""Versioned read-only contracts. Events are generated by source systems, never guessed."""
from dataclasses import dataclass
from enum import Enum
from hashlib import sha256
import inspect
import json
from typing import Any, Mapping, Protocol

CONTRACT_VERSION = 1

@dataclass(frozen=True)
class TradeEvent:
    run_id: str
    strategy_id: str
    symbol: str
    trade_id: str
    entry_ms: int
    exit_ms: int | None
    entry_price: float
    exit_price: float | None
    side: str
    quantity: float
    pnl: float | None

    @classmethod
    def parse(cls, raw: dict[str, Any]):
        e = cls(**raw)
        if e.side not in ('long','short') or e.entry_ms < 0 or e.entry_price <= 0 or e.quantity <= 0:
            raise ValueError('invalid trade event')
        if e.exit_ms is not None and e.exit_ms < e.entry_ms:
            raise ValueError('exit before entry')
        if (e.exit_ms is None) != (e.exit_price is None):
            raise ValueError('partial exit')
        return e


def align_trades(trades, start_ms, end_ms):
    """Clip display to viewport; preserve original entry and exit timestamps."""
    return [t for t in trades if t.entry_ms <= end_ms and (t.exit_ms is None or t.exit_ms >= start_ms)]


def aggregate_footprint(rows):
    """One POC per minute, tie-break to lowest price for deterministic display."""
    minutes = {}
    for r in rows:
        t, price, volume = int(r['t']), float(r['price']), float(r['volume'])
        if volume < 0: raise ValueError('negative volume')
        bucket = minutes.setdefault(t, {'t':t, 'levels':[], 'poc':None, 'poc_volume':-1.0})
        bucket['levels'].append(r)
        if volume > bucket['poc_volume'] or (volume == bucket['poc_volume'] and (bucket['poc'] is None or price < bucket['poc'])):
            bucket['poc'], bucket['poc_volume'] = price, volume
    return [minutes[t] for t in sorted(minutes)]


def poc_close_events(minutes, candles):
    """Diagnostic POC-close observations, NOT trading signals or backtest fills."""
    closes = {int(c['t']): float(c['c']) for c in candles}
    return [{'t':m['t'],'poc':m['poc'],'close':closes[m['t']], 'relation':'above' if closes[m['t']] > m['poc'] else 'below' if closes[m['t']] < m['poc'] else 'at'} for m in minutes if m['t'] in closes]


# Strategy ownership transferred from Strattester:
# strattester/strategies/{base,registry}.py and builtin/research_common.py.
# These are metadata/registry contracts only. No strategy is executed here.
STRATEGY_DATASETS = frozenset((
    'candles', 'mark_price', 'index_price', 'premium_index',
    'open_interest', 'funding', 'long_short_ratio', 'public_trades',
    'public_trade_aggregates', 'orderbook_l2', 'liquidations',
))


@dataclass(frozen=True)
class DataRequirement:
    dataset: str
    timeframes: tuple[str, ...] = ()
    required: bool = True

    def __post_init__(self):
        name = self.dataset.value if isinstance(self.dataset, Enum) else self.dataset
        if not isinstance(name, str) or name not in STRATEGY_DATASETS:
            raise ValueError('unknown strategy dataset')
        object.__setattr__(self, 'dataset', name)
        if not isinstance(self.timeframes, tuple) or any(
            not isinstance(tf, str) or not tf for tf in self.timeframes
        ):
            raise ValueError('invalid timeframes')
        if type(self.required) is not bool:
            raise ValueError('required must be boolean')


@dataclass(frozen=True)
class StrategyDefinition:
    id: str
    version: str
    requirements: tuple[DataRequirement, ...]
    implementation: type
    enabled: bool = True
    feature_versions: tuple[str, ...] = ()

    def __post_init__(self):
        if not isinstance(self.id, str) or not self.id.strip():
            raise ValueError('strategy id required')
        if not isinstance(self.version, str) or not self.version.strip():
            raise ValueError('strategy version required')
        if not isinstance(self.requirements, tuple) or any(
            not isinstance(req, DataRequirement) for req in self.requirements
        ):
            raise ValueError('invalid strategy data requirements')
        if not isinstance(self.implementation, type):
            raise ValueError('implementation must be a class')
        if type(self.enabled) is not bool:
            raise ValueError('enabled must be boolean')
        if not isinstance(self.feature_versions, tuple) or any(
            not isinstance(version, str) or not version
            for version in self.feature_versions
        ):
            raise ValueError('invalid feature versions')


def strategy_fingerprint(definition: StrategyDefinition) -> str:
    """Identity only; unchanged by enable/disable, not a scientific proof."""
    try:
        source = inspect.getsource(definition.implementation)
    except (OSError, TypeError):
        source = (
            f'{definition.implementation.__module__}.'
            f'{definition.implementation.__qualname__}'
        )
    payload = {
        'id': definition.id, 'version': definition.version,
        'requirements': [
            (req.dataset, req.timeframes, req.required)
            for req in definition.requirements
        ],
        'impl': (
            f'{definition.implementation.__module__}.'
            f'{definition.implementation.__qualname__}'
        ),
        'source_sha256': sha256(source.encode()).hexdigest(),
        'feature_versions': definition.feature_versions,
    }
    return sha256(json.dumps(payload, sort_keys=True).encode()).hexdigest()


class Strategy(Protocol):
    id: str
    version: str
    requirements: tuple[DataRequirement, ...]

    def run(self, candles, checkpoint=None): ...


class StrategyRegistry:
    """Single Terminan-owned strategy metadata registry; no data side effects."""

    def __init__(self):
        self._items = {}

    def register(self, definition: StrategyDefinition):
        if not isinstance(definition, StrategyDefinition):
            raise TypeError('strategy definition required')
        key = (definition.id, definition.version)
        if key in self._items:
            raise ValueError(f'duplicate strategy {key}')
        self._items[key] = definition

    def discover(self):
        return list(self._items.values())

    def set_enabled(self, strategy_id, version, enabled):
        if type(enabled) is not bool:
            raise ValueError('enabled must be boolean')
        old = self._items[(strategy_id, version)]
        self._items[(strategy_id, version)] = StrategyDefinition(
            old.id, old.version, old.requirements, old.implementation,
            enabled, old.feature_versions,
        )


@dataclass(frozen=True)
class HypothesisSpec:
    name: str
    family: str
    params: Mapping[str, Any]
    control: bool = False
    execution_status: str = 'SPEC_ONLY'
    signal_generator: str | None = None

    def __post_init__(self):
        if self.execution_status not in ('SPEC_ONLY', 'EXECUTABLE'):
            raise ValueError('execution_status')
        if self.execution_status == 'EXECUTABLE' and not self.signal_generator:
            raise ValueError('executable hypothesis requires signal_generator')


def executable_hypotheses(items):
    """Exclude declarative research ideas from executable strategy selection."""
    return tuple(x for x in items if x.execution_status == 'EXECUTABLE')
